class RegistrarUsuarioUseCase {
  constructor(private usuarios: UsuarioRepository) {}
  async execute({ email, senha }) {
    const usuario = Usuario.criar(email, senha)
    await this.usuarios.salvar(usuario)
    return usuario
  }
}
